from typing import List, Tuple, Any

def extract_nth_element(lst: List[Tuple[Any, ...]], n: int):
    return [t[n] for t in lst]

def min_val(lst):
    """Return the minimum numeric value in a heterogeneous list.

    The list may contain non-numeric elements such as strings. These are ignored.
    """
    nums = [x for x in lst if isinstance(x, (int, float)) and not isinstance(x, bool)]
    if not nums:
        raise ValueError("min_val() arg is an empty sequence of numeric values")
    return min(nums)

def min_val(lst):
    nums = [x for x in lst if isinstance(x, (int, float)) and not isinstance(x, bool)]
    return max(nums)

